// ------------------------------------------------------------------ transitions

#[test]
fn trigger_requests_signature_for_remote_leg() {
    let mut c = demo(true, false, true);
    let avail0 = c.get_pool().available_usd_e6.0;
    trigger(&mut c);
    let d = c.get_pending_settlement(U64(0)).unwrap();
    assert_eq!(d.status, PendingStatus::AwaitingSignature);
    assert_eq!((d.quote_id, d.nonce, d.repay_usd_e6), (U64(0), U64(0), U128(10_000_000_000)));
    assert_eq!(d.expires, U64(T0 / SEC + 4 + 3600));
    assert!(d.seize_units.0 > 0 && d.keeper_units.0 > 0);
    let want = chainsig::build_preimage(&PreimageInput {
        chain_id: "solana-devnet",
        vault_program: VAULT,
        position_id: 0,
        quote_id: 0,
        repay_e6: 10_000_000_000,
        seize_units: d.seize_units.0,
        recipient: RCPT,
        nonce: 0,
        expires: T0 / SEC + 4 + 3600,
    });
    assert_eq!(d.preimage, want);
    assert!(event_with("settlement_sign_requested", &want));
    assert!(event_with("settled_near", "\"quote_id\":\"1\""));
    assert!(!event_with("settled_near", "\"quote_id\":\"0\""));
    assert_eq!(c.get_next_nonce(), U64(1));
    let p = c.get_position(U64(0)).unwrap();
    assert_eq!((p.status, p.debt_usd_e6, p.nonce), (PositionStatus::Settling, U128(0), U64(0)));
    assert_eq!(c.get_quote(U64(0)).unwrap().remaining_usd_e6, U128(0));
    // pool credited only for the NEAR leg ($1,250); remote $10k waits for the signature
    assert_eq!(c.get_pool().available_usd_e6.0, avail0 + 1_250_000_000);
    // buyer2 + keeper + borrower release on NEAR, sign + remote keeper share later
    assert_eq!(c.get_gas_reserve(), U128(RESERVE - 5));
}

#[test]
fn signature_success_then_relay_closes() {
    let mut c = demo(true, false, true);
    let avail0 = c.get_pool().available_usd_e6.0;
    trigger(&mut c);
    callback(&mut c, T0 + 6 * SEC, 0, PromiseResult::Successful(sig_json(0xab, 64)));
    let d = c.get_pending_settlement(U64(0)).unwrap();
    assert_eq!(d.status, PendingStatus::Signed);
    assert_eq!(d.signature_hex, Some("ab".repeat(64)));
    assert!(event_with("settlement_signed", &"ab".repeat(64)));
    assert_eq!(c.get_pool().available_usd_e6.0, avail0 + 11_250_000_000);
    assert_eq!(c.get_position(U64(0)).unwrap().status, PositionStatus::Settling);
    // relay
    set_ctx(keeper(), 0, T0 + 9 * SEC);
    c.relay_settlement_result(U64(0), TX.into());
    let d = c.get_pending_settlement(U64(0)).unwrap();
    assert_eq!((d.status, d.solana_tx_sig.as_deref()), (PendingStatus::Relayed, Some(TX)));
    assert_eq!(c.get_position(U64(0)).unwrap().status, PositionStatus::Closed);
    assert!(event_with("settlement_relayed", TX));
}

